// high pass again again
// make sure to map the final output from [-1, +1] back to [0, 1]
void mainImage(out vec4 frag_col, in vec2 frag_coord)
{
    float sum_values = 0.;
    float sum_weights = 0.;
    for (int offs_y = -5; offs_y <= 5; offs_y++)
    {
        for (int offs_x = -5; offs_x <= 5; offs_x++)
        {
            float v = FETCH(frag_coord + vec2(offs_x, offs_y));

            float weight = gaussian_unnorm(
                length(vec2(offs_x, offs_y)),
                1.
            );

            sum_values += v * weight;
            sum_weights += weight;
        }
    }
    float low_pass = sum_values / sum_weights;
    float high_pass = FETCH(frag_coord) - low_pass;

    // map from [-1, +1] back to [0, 1]
    vec3 col = vec3(high_pass * .5 + .5);

    frag_col = vec4(pow(col, vec3(1. / 2.2)), 1);
}

const float SQRT_2PI = 2.506628274631;

float sq(float x)
{
    return x * x;
}

float gaussian_distribution(float x, float standard_deviation)
{
    return exp(-.5 * sq(x / standard_deviation)) / (SQRT_2PI * standard_deviation);
}

// unnormalized gaussian, doesn't add up to 1, maximum value is 1.
float gaussian_unnorm(float x, float standard_deviation)
{
    return exp(-.5 * sq(x / standard_deviation));
}

// fetch the input value from iChannel0
#define FETCH(COORD) \
(texture(iChannel0, (COORD) / vec2(textureSize(iChannel0, 0))).x)

// fetch the input and map it from [0, 1] to [-1, +1].
// this is only done in Buffer A. the final value is mapped back to
// [0, 1] in the Image tab by doing (x * .5 + .5).
#define FETCH_MAPPED(COORD) \
(FETCH(COORD) * 2. - 1.)

// high pass iChannel0 (texture)
// make sure to first map the input from [0, 1] to [-1, +1]
void mainImage(out vec4 frag_col, in vec2 frag_coord)
{
    float sum_values = 0.;
    float sum_weights = 0.;
    for (int offs_y = -5; offs_y <= 5; offs_y++)
    {
        for (int offs_x = -5; offs_x <= 5; offs_x++)
        {
            // this will map the input from [0, 1] to [-1, +1]
            float v = FETCH_MAPPED(frag_coord + vec2(offs_x, offs_y));

            float weight = gaussian_unnorm(
                length(vec2(offs_x, offs_y)),
                1.
            );

            sum_values += v * weight;
            sum_weights += weight;
        }
    }
    float low_pass = sum_values / sum_weights;
    float high_pass = FETCH_MAPPED(frag_coord) - low_pass;

    vec3 col = vec3(high_pass);

    frag_col = vec4(col, 1);
}

